const shell=(content)=>`<div class="demo">PROTOTIPO · DATOS DE EJEMPLO</div><div class="shell"><aside class="sidebar" id="sidebar"><a class="logo" href="/"><b>diana</b><span>BY LOFT · CBB</span></a><div class="role-chip">${cfg.label}</div><nav class="nav">${cfg.nav.map((x,i)=>`<button class="${i===0?'active':''}">${x}</button>`).join('')}</nav><div class="sidebar-foot"><div class="profile"><div class="avatar">${cfg.initials}</div><div><b>${cfg.name}</b><small>${cfg.label}</small></div></div><a class="view-site" href="/">← Ver página pública</a></div></aside><main class="main"><header class="topbar"><div><button class="mobile-menu" id="mobileMenu">☰</button><span class="eyebrow">SÁBADO 28 NOV · RED ROOM</span><h1>${cfg.title}</h1></div><div class="top-actions"><select class="event-select"><option>Red Room · 28 Nov</option><option>Friday Sessions · 04 Dic</option><option>Diana Nights · 12 Dic</option></select><button class="icon-btn">●</button></div></header>${content}</main></div><div class="toast" id="toast"></div>`;
const kpis=(items)=>`<section class="kpis">${items.map(x=>`<article class="kpi"><span class="label">${x[0]}</span><strong>${x[1]}</strong><span class="delta ${x[3]||''}">${x[2]}</span></article>`).join('')}</section>`;
const admin=()=>shell(`${kpis([['Venta total','Bs 48.760','+18% vs. última fecha'],['Personas ingresadas','284','de 420 confirmadas'],['Por verificar','12','comprobantes pendientes','warn'],['Stock crítico','4','productos requieren atención','warn']])}<section class="grid"><div><article class="card"><div class="card-head"><div><h2>Comprobantes pendientes</h2><p>Verificación manual antes de habilitar la entrega.</p></div><button class="link-btn">Ver todos</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Compra</th><th>Monto</th><th>Código</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${[['Camila Rojas','2 VIP','Bs 300','—'],['Jorge Salvatierra','Mesa VIP V2','Bs 1.400','ANDRES24'],['Paola Méndez','4 General','Bs 320','LUIS10']].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td class="muted">${x[3]}</td><td><span class="badge pending">Pendiente</span></td><td><button class="action primary approve">Revisar</button></td></tr>`).join('')}</tbody></table></div></article><article class="card"><div class="card-head"><div><h2>Ventas por hora</h2><p>Entradas, mesas y barra combinadas.</p></div><span class="badge ok">En vivo</span></div><div class="bar-chart">${[['20h',24],['21h',43],['22h',69],['23h',92],['00h',76],['01h',58],['02h',35]].map(x=>`<div class="bar-col"><i style="height:${x[1]}%"></i><span>${x[0]}</span></div>`).join('')}</div></article></div><aside><article class="card"><div class="card-head"><div><h2>Distribución de ingresos</h2><p>Bs 48.760 acumulados.</p></div></div><div class="breakdown">${[['Barra','52%',52],['Mesas','27%',27],['Entradas','21%',21]].map(x=>`<div class="break-row"><span>${x[0]}</span><div class="track"><i style="width:${x[2]}%"></i></div><b>${x[1]}</b></div>`).join('')}</div></article><article class="card"><div class="card-head"><div><h2>Evento activo</h2><p>Precios editables por fecha.</p></div></div><div class="stack"><div class="order-line"><span>General</span><b>Bs 80</b></div><div class="order-line"><span>VIP</span><b>Bs 150</b></div><div class="order-line"><span>Mesa general</span><b>Bs 1.000</b></div><div class="order-line"><span>Mesa VIP</span><b>Bs 1.400</b></div><button class="btn secondary demo-action">Editar precios</button></div></article><article class="card"><div class="card-head"><div><h2>Relacionadores</h2><p>Ranking por ventas atribuidas.</p></div></div><div class="stack"><div class="order-line"><span>1. Andrés M.</span><b>26 ventas</b></div><div class="order-line"><span>2. Luis G.</span><b>19 ventas</b></div><div class="order-line"><span>3. Carla V.</span><b>14 ventas</b></div></div></article></aside></section>`);
const puerta=()=>shell(`${kpis([['Confirmados','420','para esta fecha'],['Ingresaron','284','67,6% del total'],['Venta en puerta','Bs 6.480','efectivo, tarjeta y QR'],['Por entregar','36','manillas pendientes','warn']])}<div class="notice">Las compras online solo pueden entregarse cuando el administrador haya verificado el comprobante. La persona que reservó una mesa recoge todas las manillas.</div><section class="grid"><div><article class="card"><div class="card-head"><div><h2>Buscar compra online</h2><p>Nombre, teléfono o código de solicitud.</p></div></div><div class="search-row"><input class="search" id="doorSearch" placeholder="Ej. Camila Rojas o DF-2819"><button class="btn" id="searchBuyer">Buscar</button></div><div class="result" id="doorResult"><div class="result-head"><div><h3>Camila Rojas</h3><p>Solicitud #DF-2819 · 707 445 21</p></div><span class="badge ok">Pago verificado</span></div><div class="order-lines"><div class="order-line"><span>2 entradas VIP</span><b>Bs 300</b></div><div class="order-line"><span>Fecha</span><b>28 nov · 22:00</b></div><div class="order-line"><span>Relacionador</span><b>Sin código</b></div></div><div class="result-actions"><button class="btn deliver">Entregar 2 manillas</button><button class="btn secondary demo-action">Ver comprobante</button></div></div></article><article class="card"><div class="card-head"><div><h2>Últimos ingresos</h2><p>Registro de entrega y acceso.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Hora</th><th>Cliente</th><th>Acceso</th><th>Operador</th></tr></thead><tbody><tr><td>23:42</td><td>Mario Pinto</td><td><span class="badge ok">VIP</span></td><td>Marco A.</td></tr><tr><td>23:39</td><td>Sofía Rocha</td><td><span class="badge">General</span></td><td>Marco A.</td></tr><tr><td>23:35</td><td>Mesa G4</td><td>10 manillas</td><td>Lucía T.</td></tr></tbody></table></div></article></div><aside><article class="card"><div class="card-head"><div><h2>Venta en puerta</h2><p>Registra el cobro y la entrega.</p></div></div><form class="pos-form" id="doorPos"><label>Tipo<select id="doorType"><option data-price="80">General · Bs 80</option><option data-price="150">VIP · Bs 150</option></select></label><label>Cantidad<select id="doorQty"><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option><option>10</option></select></label><label>Método de pago<select><option>Efectivo</option><option>Tarjeta</option><option>QR</option></select></label><label>Código relacionador<input placeholder="Opcional"></label><div class="pos-total"><span>Total</span><strong id="doorTotal">Bs 80</strong></div><button class="btn full" type="submit">Registrar venta</button></form></article></aside></section>`);
const barra=()=>shell(`${kpis([['Venta de barra','Bs 25.350','+12% vs. última fecha'],['Órdenes','186','ticket promedio Bs 136'],['Mesa con saldo','18','crédito de consumo activo'],['Stock crítico','4','productos por reponer','warn']])}<section class="grid"><div><article class="card"><div class="card-head"><div><h2>Productos</h2><p>Selecciona para agregar a la venta.</p></div></div><div class="tabs"><button class="tab active">Todos</button><button class="tab">Botellas</button><button class="tab">Cervezas</button><button class="tab">Shots</button><button class="tab">Otros</button></div><div class="catalog">${[['Fernet 750 ml','Botellas','Bs 380'],['Johnnie Walker','Botellas','Bs 520'],['Corona','Cervezas','Bs 35'],['Huari','Cervezas','Bs 30'],['Shot Jäger','Shots','Bs 35'],['Energizante','Otros','Bs 30'],['Agua','Otros','Bs 15'],['Cigarrillos','Otros','Bs 45'],['Vodka 750 ml','Botellas','Bs 350']].map(x=>`<button class="product" data-name="${x[0]}" data-price="${x[2].replace(/\D/g,'')}"><span>${x[1]}</span><b>${x[0]}</b><strong>${x[2]}</strong></button>`).join('')}</div></article></div><aside><article class="card"><div class="card-head"><div><h2>Venta actual</h2><p id="cartCount">Sin productos</p></div><button class="link-btn" id="clearCart">Limpiar</button></div><div class="cart-list" id="cartList"><span class="muted">Agrega productos desde el catálogo.</span></div><div class="cart-total"><span>Total</span><strong id="cartTotal">Bs 0</strong></div><div class="stack"><select id="barPayment"><option>Efectivo</option><option>Tarjeta</option><option>QR</option><option>Consumo de mesa</option></select><button class="btn full" id="chargeBar">Cobrar venta</button></div></article><article class="card"><div class="card-head"><div><h2>Cobrar a mesa</h2><p>El valor reservado funciona como saldo.</p></div></div><div class="credit"><small>MESA VIP · V2</small><strong>Bs 860</strong><span class="muted">Saldo disponible de Bs 1.400</span></div><div class="search-row" style="margin-top:12px"><input class="search" placeholder="Buscar mesa"><button class="btn secondary demo-action">Buscar</button></div></article></aside></section>`);
const relacionador=()=>shell(`${kpis([['Entradas general','18','ventas atribuidas'],['Entradas VIP','8','ventas atribuidas'],['Mesas general','2','reservas atribuidas'],['Mesas VIP','1','reserva atribuida']])}<section class="grid"><div><article class="card"><div class="card-head"><div><h2>Mis ventas</h2><p>Solo se contabilizan pagos verificados.</p></div><span class="badge ok">340 puntos</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Cliente</th><th>Producto</th><th>Monto</th><th>Estado</th></tr></thead><tbody><tr><td>28 nov</td><td>Jorge Salvatierra</td><td>Mesa VIP V2</td><td>Bs 1.400</td><td><span class="badge ok">Verificado</span></td></tr><tr><td>28 nov</td><td>Laura Arce</td><td>2 VIP</td><td>Bs 300</td><td><span class="badge pending">Pendiente</span></td></tr><tr><td>28 nov</td><td>Gustavo León</td><td>4 General</td><td>Bs 320</td><td><span class="badge ok">Verificado</span></td></tr></tbody></table></div></article><article class="card"><div class="card-head"><div><h2>Puntos por evento</h2><p>El administrador define premios y condiciones.</p></div></div><div class="bar-chart">${[['SEP',35],['OCT',58],['08 NOV',72],['15 NOV',48],['28 NOV',90]].map(x=>`<div class="bar-col"><i style="height:${x[1]}%"></i><span>${x[0]}</span></div>`).join('')}</div></article></div><aside><article class="card"><div class="card-head"><div><h2>Mi código</h2><p>El cliente lo ingresa al comprar.</p></div></div><div class="share-box"><span class="muted">CÓDIGO PERSONAL</span><div class="share-code">ANDRES24</div><button class="btn full copy-code">Copiar código</button></div></article><article class="card"><div class="card-head"><div><h2>Compartir compra</h2><p>El QR de pago es el mismo de Diana.</p></div></div><div class="stack"><button class="btn demo-action">Compartir página de entradas</button><button class="btn secondary demo-action">Compartir reservas de mesas</button></div></article><article class="card"><div class="card-head"><div><h2>Próximo nivel</h2><p>Información visible para administración.</p></div></div><div class="credit"><small>PUNTOS ACTUALES</small><strong>340</strong><span class="muted">Faltan 160 puntos para 500</span></div></article></aside></section>`);
app.innerHTML=role==='puerta'?puerta():role==='barra'?barra():role==='relacionador'?relacionador():admin();
const toast=(msg)=>{const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)};
document.querySelector('#mobileMenu')?.addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));
document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast(`${b.textContent}: vista demostrativa`)}));
document.querySelectorAll('.demo-action').forEach(b=>b.addEventListener('click',()=>toast('Acción disponible en la versión conectada al sistema')));
document.querySelectorAll('.approve').forEach(b=>b.addEventListener('click',()=>{b.closest('tr').querySelector('.badge').className='badge ok';b.closest('tr').querySelector('.badge').textContent='Verificado';b.textContent='Aprobado';b.disabled=true;toast('Pago aprobado y habilitado en puerta')}));
document.querySelector('#searchBuyer')?.addEventListener('click',()=>toast('Compra encontrada: pago verificado'));
document.querySelector('.deliver')?.addEventListener('click',e=>{e.currentTarget.textContent='Manillas entregadas';e.currentTarget.disabled=true;toast('Entrega registrada correctamente')});
const calcDoor=()=>{const s=document.querySelector('#doorType');const p=+s.options[s.selectedIndex].dataset.price;const q=+document.querySelector('#doorQty').value;document.querySelector('#doorTotal').textContent=`Bs ${p*q}`};
document.querySelector('#doorType')?.addEventListener('change',calcDoor);document.querySelector('#doorQty')?.addEventListener('change',calcDoor);
document.querySelector('#doorPos')?.addEventListener('submit',e=>{e.preventDefault();toast('Venta registrada y manillas habilitadas')});
let cart=[];const renderCart=()=>{const list=document.querySelector('#cartList');if(!list)return;list.innerHTML=cart.length?cart.map(x=>`<div class="cart-item"><span>${x.name}</span><b>Bs ${x.price}</b></div>`).join(''):'<span class="muted">Agrega productos desde el catálogo.</span>';document.querySelector('#cartTotal').textContent=`Bs ${cart.reduce((a,x)=>a+x.price,0)}`;document.querySelector('#cartCount').textContent=cart.length?`${cart.length} producto${cart.length>1?'s':''}`:'Sin productos'};
document.querySelectorAll('.product').forEach(p=>p.addEventListener('click',()=>{cart.push({name:p.dataset.name,price:+p.dataset.price});renderCart()}));
document.querySelector('#clearCart')?.addEventListener('click',()=>{cart=[];renderCart()});
document.querySelector('#chargeBar')?.addEventListener('click',()=>{if(!cart.length)return toast('Agrega al menos un producto');toast('Venta de barra registrada');cart=[];renderCart()});
document.querySelector('.copy-code')?.addEventListener('click',()=>{navigator.clipboard?.writeText('ANDRES24');toast('Código ANDRES24 copiado')});
